import heapq

def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by start time
    intervals.sort()

    # Min-heap to keep track of end times of meetings in rooms
    heap = []

    for start, end in intervals:
        # If the earliest ending meeting has ended by the start of the current one, reuse that room
        if heap and heap[0] <= start:
            heapq.heappop(heap)
        # Add the end time of the current meeting to the heap
        heapq.heappush(heap, end)

    # The size of the heap is the minimum number of rooms needed
    return len(heap)

