import bisect

def solve(nums1, nums2):
    # Sort nums2 to enable binary search
    sorted_nums2 = sorted(nums2)

    # Count occurrences in nums1
    count_nums1 = {}
    for num in nums1:
        count_nums1[num] = count_nums1.get(num, 0) + 1

    result = []
    # For each number in nums1, check if it exists in nums2 with available count
    for num in nums1:
        if count_nums1[num] > 0:
            # Binary search for num in sorted_nums2
            index = bisect.bisect_left(sorted_nums2, num)
            if index < len(sorted_nums2) and sorted_nums2[index] == num:
                # Found a match, decrement count in nums1
                count_nums1[num] -= 1
                result.append(num)

    return result

