            mid = (low + high) // 2
            if sorted_nums[mid] < i:
                low = mid
            else:
                high = mid

    @staticmethod
    def run_length(sorted_nums, i):
        """bisection search for sorted nums"""
        (low, high) = (0, len(sorted_nums) - 1)
        while True:
            if high - low <= 1:
                break
            mid = (low + high) // 2
            if sorted_nums[mid] < i + 2:
                low = mid
            else:
                high = mid
        if high == low:
            if sorted_nums[high] != i + 1:
                low -= 1
        return high - low + 1

