            for c, v in count.items():
                if c in next_count:
                    if count[c] != next_count[c]:
                        return False
                else:
                    next_count[c] = v

            # For every entry in next_count, check if covered in count
            for c, v in next_count.items():
                if c not in count or count[c] != v:
                    return False

            return True

        # Initialize necessary variables
        i = 0
        args = strs[:+1]
        while True:
            yield i, args
            if i >= len(args):
                break
            i += 1
            args = update_state(i, args)

