    return Image.open(image_path).convert('L')

def calculate_gradient(image):
    image_np = np.array(image)
    grad_x = np.gradient(image_np, axis=1)
    grad_y = np.gradient(image_np, axis=0)
    return grad_x, grad_y

def reconstruct_image(grad_x, grad_y):
    heights, widths = grad_x.shape
    recon_np = np.zeros((heights, widths))
    for y in range(heights):
        for x in range(widths):
            recon_np[y, x] = grad_x[y, x]**2 + grad_y[y, x]**2
    return Image.fromarray(recon_np.astype(np.uint8))

