    # 输入验证
    if not citations:
        return 0

    # 确保 citations 的每个元素都在合理范围之内
    for citation in citations:
        if not 0 <= citation <= 100000:
            raise ValueError("Invalid citation count: all values must be between 0 and 100,000 inclusive.")

