def analyze_data(data):
    analysis_results = []
    for num in data:
        if num < 100:
            analysis_results.append("Low activity")
        elif num < 500:
            analysis_results.append("Medium activity")
        else:
            analysis_results.append("High activity")
    return analysis_results

