        except EOFError:
            break

    v_min = candidates[0][0]
    n_remain = 0
    for v, n in candidates:
        if n == 1:
            if v > v_min:
                yield v
        else:
            n_remain -= n - 1
            if v > v_min:
                for _ in range(n - 1):
                    yield v

