import random
import chess

class ChessAI:
    def __init__(self):
        self.board = chess.Board()

    def get_best_move(self, depth):
        return self.minimax(self.board, depth, -float('inf'), float('inf'), True)[1]

    def minimax(self, board, depth, alpha, beta, is_maximizing):
        if depth == 0 or board.is_game_over():
            return self.evaluate_board(board), None

        if is_maximizing:
            max_eval = -float('inf')
            best_move = None
            for move in board.legal_moves:
                board.push(move)
                eval, _ = self.minimax(board, depth - 1, alpha, beta, False)
                board.pop()
                if eval > max_eval:
                    max_eval = eval
                    best_move = move
                alpha = max(alpha, eval)
                if alpha >= beta:
                    break
            return max_eval, best_move
        else:
            min_eval = float('inf')
            best_move = None
            for move in board.legal_moves:
                board.push(move)
                eval, _ = self.minimax(board, depth - 1, alpha, beta, True)
                board.pop()
                if eval < min_eval:
                    min_eval = eval
                    best_move = move
                beta = min(beta, eval)
                if alpha >= beta:
                    break
            return min_eval, best_move

    def evaluate_board(self, board):
        evaluation = 0
        for i in range(64):
            piece = board.piece_at(i)
            if piece is not None:
                if piece.color == chess.WHITE:
                    evaluation += piece.value
                else:
                    evaluation -= piece.value
        return evaluation

    def visualize_board(self):
        pygame.init()
        board = pygame.image.load(pygame.image.get_default_font())
        screen = pygame.display.set_mode((640, 640))
        screen.blit(board, (0, 0))
        pygame.display.flip()
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    return None
            pygame.display.flip()

    def play_game(self):
        while not self.board.is_game_over():
            self.move_piece(self.board, random.choice(list(self.board.legal_moves)))
            if self.board.is_game_over():
                break
            best_move = self.get_best_move(3)
            self.move_piece(self.board, best_move)
            self.visualize_board()

    def move_piece(self, board, move):
        board.push(move)

if __name__ == "__main__":
    ai = ChessAI()
    ai.play_game()

