        if(root == nullptr){
            return {0, 0};
        }
        auto leftDfs = DFS(root->left);
        auto rightDfs = DFS(root->right);

        auto robbed = root->val + leftDfs.second + rightDfs.second;
        auto notRobbed = max(leftDfs.first, leftDfs.second) + max(rightDfs.first, rightDfs.second);

        return {notRobbed, robbed};
    }
};

