    """Rebuild heap by 'trickle up' from index i. Change the list h passed as a parameter so that a valid heap is stored. Return None.
    """
    l = 2 * i + 1
    r = 2 * i + 2
    jar = i
    if l < len(h):
        if h[l] > h[jar]:
            jar = l
    if r < len(h) and h[r] > h[jar]:
