def solve(a, b):
    if a is None:
        return "00"

    def bin_to_int(bitstring):
        return int(bitstring, 2)

    def int_to_bin(num, length):
        return bin(num)[2:].zfill(length)

    a_int = bin_to_int(a)
    b_int = bin_to_int(b)

    def int_add(x, y):
        x_bin = bin(x)[2:].zfill(3000)
        y_bin = bin(y)[2:].zfill(3000)
        result = int(x_bin, 2) + int(y_bin, 2)
        return int_to_bin(result, 3000)

    def int_subtract(x, y):
        x_bin = bin(x)[2:].zfill(3000)
        y_bin = bin(y)[2:].zfill(3000)
        result = int(x_bin, 2) - int(y_bin, 2)
        return int_to_bin(result, 3000)

    def int_multiply(x, y):
        x_bin = bin(x)[2:].zfill(3000)
        y_bin = bin(y)[2:].zfill(3000)
        result = int(x_bin, 2) * int(y_bin, 2)
        return int_to_bin(result, 3000)

    remainder = a_int
    divisor = b_int

    while remainder >= divisor:
        remainder = int_subtract(remainder, divisor)

    return bin(remainder)[2:].zfill(len(b))

