def validate_data(data):
    """
    Validate the data to ensure there are no negatives, unmapped values or C inference predictive error.
    """
    try:
        if any(value < 0 for value in data):
            raise ValueError("Negative value found")
        if any(value in ["unmapped", "not_valid"] for value in data):
            raise ValueError("Unmapped or invalid value found")
    except Exception as e:
        print(f"Validation error: {e}")
        return False

    return True

