        if nums[a] > 1:
            return 1

        # binary search on nums
        mid = (a + b) // 2
        if nums[mid] > mid + 1:
            return smallest_missing(a, mid, elts)
        else:
            return smallest_missing(mid + 1, b, elts)

    return smallest_missing(0, n, nums)

