def solve(intervals):
    if not intervals:
        return 0

    # Separate start and end times
    starts = sorted(start for start, end in intervals)
    ends = sorted(end for start, end in intervals)

    rooms = 0
    end_ptr = 0

    for start in starts:
        # A meeting starts, check if a room is free
        if start >= ends[end_ptr]:
            end_ptr += 1
        else:
            rooms += 1

    return rooms

