def solve(strs):
    from collections import defaultdict

    groups = defaultdict(list)

    for s in strs:
        # Count the frequency of each character
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1
        # Convert the count to a tuple to use as a key
        groups[tuple(count)].append(s)

    return list(groups.values())

